package dialect

import (
	"errors"

	"github.com/jackc/pgx/v5/pgconn"
	"reflect"
)

// ParsePg normalises a PG driver error into a
// ConstraintError.
//
// Storage generated from 0.2 on opens PostgreSQL through pgx, whose
// server errors are `*pgconn.PgError`. Storage generated by an earlier
// compiler opens it through lib/pq, and a project that moves to this SDK
// before it regenerates still runs that code: its `*pq.Error` must keep
// meaning what it meant. That error is recognised by shape, not by type
// (PgSQLError), so the SDK does not depend on lib/pq for it.
//
// Returns (nil, false) when err is not a PG constraint
// violation — caller treats as internal/unrecognised and
// logs the raw error.
//
// SQLSTATE → Kind mapping:
//
//	23505 → unique
//	23503 → fk
//	23514 → check
//	23502 → not_null
//	23P01 → exclusion
//
// Other SQLSTATE classes (40001 serialization, 40P01 deadlock,
// 22001 string truncation, …) are NOT constraint violations
// — they fall through with ok=false. Wrap classifies them
// separately into retryable / internal categories.
func ParsePg(err error) (*ConstraintError, bool) {
	pe, ok := PgSQLError(err)
	if !ok {
		return nil, false
	}
	return pgFromFields(pe.Code, pe.Constraint, pe.Table, pe.Column)
}

// PgServerError is the part of a PostgreSQL server error w17 reads, from
// either driver.
type PgServerError struct {
	Code       string // SQLSTATE
	Constraint string
	Table      string
	Column     string
}

// PgSQLError finds a PostgreSQL server error in err's chain: pgx's
// `*pgconn.PgError`, or any error with a `SQLState() string` method and
// lib/pq's field names (`Constraint`, `Table`, `Column`) — lib/pq's
// `*pq.Error`, raised by storage generated before 0.2.
func PgSQLError(err error) (PgServerError, bool) {
	if err == nil {
		return PgServerError{}, false
	}
	var pgxErr *pgconn.PgError
	if errors.As(err, &pgxErr) {
		return PgServerError{Code: pgxErr.Code, Constraint: pgxErr.ConstraintName, Table: pgxErr.TableName, Column: pgxErr.ColumnName}, true
	}
	var st interface{ SQLState() string }
	if !errors.As(err, &st) {
		return PgServerError{}, false
	}
	out := PgServerError{Code: st.SQLState()}
	v := reflect.ValueOf(st)
	for v.Kind() == reflect.Pointer && !v.IsNil() {
		v = v.Elem()
	}
	if v.Kind() == reflect.Struct {
		field := func(name string) string {
			if f := v.FieldByName(name); f.IsValid() && f.Kind() == reflect.String {
				return f.String()
			}
			return ""
		}
		out.Constraint, out.Table, out.Column = field("Constraint"), field("Table"), field("Column")
	}
	return out, out.Code != ""
}

// pgFromFields builds a ConstraintError from the structured
// pieces of a PostgreSQL server error (PgSQLError).
func pgFromFields(sqlstate, constraint, table, column string) (*ConstraintError, bool) {
	kind, ok := pgKind(sqlstate)
	if !ok {
		return nil, false
	}
	ce := &ConstraintError{
		Kind:  kind,
		Name:  constraint,
		Table: table,
	}
	if column != "" {
		ce.Columns = []string{column}
	}
	return ce, true
}

func pgKind(sqlstate string) (string, bool) {
	switch sqlstate {
	case "23505":
		return KindUnique, true
	case "23503":
		return KindFK, true
	case "23514":
		return KindCheck, true
	case "23502":
		return KindNotNull, true
	case "23P01":
		return KindExclusion, true
	}
	return "", false
}
